Awesome, an expert! =)<P>

So, is it feasible?<P>

<H5> update</H5><P>

Looks good to me, even with core modules. =)<P>


<c>
use v5.12;                              # enable say & strict
use warnings;

{
    package MySay;

    use Data::Dump qw/pp dd/;
    use Carp;
    require Tie::Handle;

    our @ISA = qw(Tie::Handle);


    sub TIEHANDLE {
        #carp pp '\@_: ', \@_;
        bless \ my $i, shift
    }

    sub PRINT {
        my $self = shift;
        print STDOUT "$_" for @_
    }

    sub new {
        my $self = shift;

        open my $fh, ">&STDOUT";
        tie *$fh, 'MySay';
        return($fh);
    }

    # sub DESTROY {
    #     print STDOUT "DESTROY";
    #     # my $self = shift;
    #     select(STDOUT);
    # }
}



{
    package main;

    # ----  test vars
    $_='$_';
    my @a = map { "\$a[$_]" } 0..2;
    my @b;


    {

        select MySay->new();

        say;

        say @b;

        say @a;

        select(STDOUT)
    }


    say "AF","TER"
}
</c>
